import boto3
from config import RENDERS_BUCKET, DOWNLOAD_URL_EXPIRY_SECONDS

s3_client = boto3.client("s3")


def upload_render(key: str, body: bytes, content_type: str) -> None:
    """Upload a rendered file to S3."""
    s3_client.put_object(
        Bucket=RENDERS_BUCKET,
        Key=key,
        Body=body,
        ContentType=content_type,
    )


def generate_download_url(s3_key: str, filename: str = "poster.pdf") -> str:
    """Generate a presigned download URL."""
    return s3_client.generate_presigned_url(
        "get_object",
        Params={
            "Bucket": RENDERS_BUCKET,
            "Key": s3_key,
            "ResponseContentDisposition": f'attachment; filename="{filename}"',
        },
        ExpiresIn=DOWNLOAD_URL_EXPIRY_SECONDS,
    )
"}

