import json
import sys
import os

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", ".."))

from shared.apple_music import search_albums
from shared.validators import api_response


def handler(event, context):
    params = event.get("queryStringParameters") or {}
    query = params.get("q", "").strip()
    limit = min(int(params.get("limit", "10")), 25)

    if len(query) < 2:
        return api_response(400, {"error": "Query must be at least 2 characters"})

    try:
        results = search_albums(query, limit=limit)
        return api_response(200, {"results": results})
    except Exception as e:
        print(f"[ERROR] Apple Music search failed: {e}")
        return api_response(502, {"error": "Apple Music search unavailable"})
"}

